# -*- coding: utf-8 -*-
import json, os, sys
BASE=os.path.dirname(os.path.abspath(__file__))
OUT=sys.argv[1] if len(sys.argv)>1 else os.path.join(os.path.dirname(BASE),"marcas.html")
data=json.load(open(os.path.join(BASE,"marcas_data.json"),encoding="utf-8"))
TPL='<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Marcas & Embaixadores · Publination</title>\n<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,400;0,500;0,600;0,700;0,800;1,700&display=swap" rel="stylesheet">\n<style>\n:root{--bg:#0f100e;--card:#1b1c19;--line:rgba(255,247,207,.10);--line2:rgba(255,247,207,.16);--ink:#FFF7CF;--ink2:#c7c2ac;--ink3:#8f8b7c;--brand:#D9094F;}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{background:radial-gradient(1200px 600px at 80% -10%,#1a1b17,var(--bg) 55%) fixed,var(--bg);color:var(--ink);font-family:"Poppins",system-ui,sans-serif;-webkit-font-smoothing:antialiased;font-size:14px;min-height:100vh}\n.nav{display:flex;align-items:center;gap:6px;padding:14px 22px;border-bottom:1px solid var(--line);flex-wrap:wrap;position:sticky;top:0;background:rgba(15,16,14,.9);backdrop-filter:blur(10px);z-index:10}\n.nav .brand{font-weight:800;font-size:18px;letter-spacing:-.03em;color:var(--ink);text-decoration:none;margin-right:8px}\n.nav .brand i{font-style:italic;font-weight:700}.nav .sp{flex:1}\n.nav a.lnk{color:var(--ink2);text-decoration:none;font-size:13px;font-weight:500;padding:7px 13px;border-radius:999px}\n.nav a.lnk:hover{color:var(--ink);background:rgba(255,247,207,.06)}\n.nav a.lnk.on{background:var(--brand);color:#fff}\n.wrap{max-width:1180px;margin:0 auto;padding:28px 22px 80px}\n.eyebrow{font-size:10.5px;font-weight:600;text-transform:uppercase;letter-spacing:.16em;color:var(--brand)}\nh1{font-size:27px;font-weight:700;letter-spacing:-.02em;margin:6px 0 3px}\n.sub{color:var(--ink3);font-size:13px;margin-bottom:18px}\n.searchbar{position:sticky;top:64px;background:rgba(15,16,14,.92);backdrop-filter:blur(8px);padding:12px 0 12px;z-index:9;margin-bottom:6px}\n#q{width:100%;padding:14px 16px;font-size:16px;background:#141513;color:var(--ink);border:1px solid var(--line2);border-radius:14px;font-family:inherit}\n#q:focus{outline:none;border-color:var(--brand)}#q::placeholder{color:var(--ink3)}\n.kpis{display:flex;gap:14px;flex-wrap:wrap;margin:10px 0 6px;font-size:12px;color:var(--ink3)}.kpis b{color:var(--ink)}\n.flabel{font-size:9.5px;text-transform:uppercase;letter-spacing:.09em;color:var(--ink3);font-weight:600;margin:8px 0 5px}\n.chipsrow{display:flex;gap:7px;flex-wrap:wrap}\n.fchip{font-size:12px;padding:5px 12px;border-radius:999px;border:1px solid var(--line2);background:transparent;color:var(--ink2);cursor:pointer}\n.fchip:hover{border-color:var(--ink3)}.fchip.on{background:var(--brand);color:#fff;border-color:var(--brand)}\n.gchip.on{background:#FBD14E;color:#141513;border-color:#FBD14E}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:14px;margin-top:16px}\n.mcard{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px 18px}\n.mtitle{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:2px}\n.mtitle .mn{font-size:17px;font-weight:700}.mtitle .segtag{font-size:10.5px;color:var(--ink3)}\n.gtag{font-size:9.5px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#FBD14E;background:rgba(251,209,78,.12);padding:2px 8px;border-radius:6px}\n.mline{font-size:11px;color:var(--ink3);margin:4px 0 12px}\n.seclabel{font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--ink3);margin:12px 0 6px;display:flex;align-items:center;gap:6px}\n.emb{color:#FBD14E}\n.people{display:flex;flex-wrap:wrap;gap:6px}\n.pchip{display:inline-flex;align-items:center;gap:5px;font-size:12.5px;padding:5px 11px;border-radius:999px;text-decoration:none;background:rgba(255,247,207,.06);color:var(--ink);border:1px solid var(--line)}\n.pchip:hover{border-color:var(--brand)}\n.pchip.embx{background:rgba(251,209,78,.14);border-color:rgba(251,209,78,.4);color:#FBD14E;font-weight:600}\n.pchip .ig{opacity:.55;font-size:11px}\n.empty{text-align:center;color:var(--ink3);padding:40px}\nmark{background:rgba(251,209,78,.35);color:var(--ink);border-radius:3px;padding:0 2px}\n</style>\n</head>\n<body>\n<div class="nav">\n  <a class="brand" href="index.html">PUBLI<i>NATION</i></a><span class="sp"></span>\n  <a class="lnk" href="pautas.html">Pautas</a>\n  <a class="lnk" href="organograma.html">Organograma</a>\n  <a class="lnk on" href="marcas.html">Marcas</a>\n  <a class="lnk" href="publigif.html">PubliGIF</a>\n  <a class="lnk" href="estimativas.html">Estimativas</a>\n  <a class="lnk" href="mapeamento.html">Mapeamento</a>\n</div>\n<div class="wrap">\n  <div class="eyebrow">Publination · 2026</div>\n  <h1>Marcas & Embaixadores</h1>\n  <div class="sub">Busca rápida: digite a marca, o nome ou o @ e veja quem é embaixador e os AONs de cada marca.</div>\n  <div class="searchbar">\n    <input id="q" type="search" placeholder="🔎 Buscar marca, nome ou @… (ex: Eudora, Jade Picon, Nescau)" autofocus>\n    <div class="kpis" id="kpis"></div>\n    <div class="flabel">Cliente</div>\n    <div class="chipsrow" id="grupos"></div>\n    <div class="flabel">Marca</div>\n    <div class="chipsrow" id="chips"></div>\n  </div>\n  <div id="results" class="grid"></div>\n  <div id="empty" class="empty" style="display:none">Nada encontrado. Tenta outra marca, nome ou @.</div>\n</div>\n<script>\nconst DATA=__DATA__;\nconst norm=s=>(s||\'\').toLowerCase().normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\');\nconst brandsMap={};\nDATA.forEach(r=>{ const k=r.marca; (brandsMap[k]=brandsMap[k]||{marca:k,grupo:r.grupo,seg:r.seg,linha:r.linha,emb:[],aon:[]});\n  (r.papel===\'EMBAIXADOR\'?brandsMap[k].emb:brandsMap[k].aon).push(r); });\nconst brands=Object.values(brandsMap).sort((a,b)=> (a.grupo+a.marca).localeCompare(b.grupo+b.marca));\nconst grupos=[...new Set(DATA.map(r=>r.grupo))];\nlet activeGrupo=null, activeBrand=null;\nfunction esc(s){return (s||\'\').replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\');}\nfunction mark(t,q){ if(!q)return esc(t); const i=norm(t).indexOf(norm(q)); if(i<0)return esc(t); return esc(t.slice(0,i))+\'<mark>\'+esc(t.slice(i,i+q.length))+\'</mark>\'+esc(t.slice(i+q.length)); }\nfunction chip(r,q){ const cls=r.papel===\'EMBAIXADOR\'?\'pchip embx\':\'pchip\';\n  const label=r.nome?mark(r.nome,q):(\'@\'+mark(r.h,q));\n  const arrow=r.url?\' <span class="ig">↗</span>\':\'\';\n  const inner=label+arrow;\n  const title=r.h?(\'@\'+r.h):\'\';\n  return r.url?(\'<a class="\'+cls+\'" title="\'+esc(title)+\'" href="\'+r.url+\'" target="_blank" rel="noopener">\'+inner+\'</a>\'):(\'<span class="\'+cls+\'" title="\'+esc(title)+\'">\'+inner+\'</span>\'); }\nfunction matchRow(r,nq){ return norm(r.nome).includes(nq)||norm(r.h).includes(nq); }\nfunction render(){\n  const q=document.getElementById(\'q\').value.trim(); const nq=norm(q);\n  let list=brands;\n  if(activeGrupo) list=list.filter(b=>b.grupo===activeGrupo);\n  if(activeBrand) list=list.filter(b=>b.marca===activeBrand);\n  if(nq) list=list.filter(b=> norm(b.marca).includes(nq)||norm(b.seg).includes(nq)||b.emb.concat(b.aon).some(r=>matchRow(r,nq)) );\n  const res=document.getElementById(\'results\');\n  document.getElementById(\'empty\').style.display=list.length?\'none\':\'block\';\n  res.innerHTML=list.map(b=>{\n    let emb=b.emb, aon=b.aon;\n    const brandMatches = nq && (norm(b.marca).includes(nq)||norm(b.seg).includes(nq));\n    if(nq && !brandMatches){ emb=b.emb.filter(r=>matchRow(r,nq)); aon=b.aon.filter(r=>matchRow(r,nq)); }\n    const embHtml=emb.length?(\'<div class="seclabel"><span class="emb">★</span> Embaixador\'+(emb.length>1?\'es\':\'\')+\'</div><div class="people">\'+emb.map(r=>chip(r,nq)).join(\'\')+\'</div>\'):\'\';\n    const aonHtml=aon.length?(\'<div class="seclabel">AON · \'+aon.length+\'</div><div class="people">\'+aon.map(r=>chip(r,nq)).join(\'\')+\'</div>\'):\'\';\n    return \'<div class="mcard"><div class="mtitle"><span class="mn">\'+mark(b.marca,nq)+\'</span><span class="segtag">\'+esc(b.seg)+\'</span><span class="gtag">\'+esc(b.grupo)+\'</span></div><div class="mline">Linha: \'+esc(b.linha||\'—\')+\'</div>\'+embHtml+aonHtml+\'</div>\';\n  }).join(\'\');\n}\nfunction buildGrupos(){\n  const c=document.getElementById(\'grupos\');\n  c.innerHTML=\'<span class="fchip gchip\'+(activeGrupo?\'\':\' on\')+\'" onclick="setGrupo(null)">Todos</span>\'+\n    grupos.map(g=>\'<span class="fchip gchip\'+(activeGrupo===g?\' on\':\'\')+\'" onclick="setGrupo(\\\'\'+g.replace(/\'/g,"\\\\\'")+\'\\\')">\'+esc(g)+\'</span>\').join(\'\');\n}\nfunction buildChips(){\n  const c=document.getElementById(\'chips\');\n  let bs=brands; if(activeGrupo) bs=bs.filter(b=>b.grupo===activeGrupo);\n  c.innerHTML=\'<span class="fchip\'+(activeBrand?\'\':\' on\')+\'" onclick="setBrand(null)">Todas</span>\'+\n    bs.map(b=>\'<span class="fchip\'+(activeBrand===b.marca?\' on\':\'\')+\'" onclick="setBrand(\\\'\'+b.marca.replace(/\'/g,"\\\\\'")+\'\\\')">\'+esc(b.marca)+\'</span>\').join(\'\');\n}\nfunction setGrupo(g){ activeGrupo=g; activeBrand=null; document.getElementById(\'q\').value=\'\'; buildGrupos(); buildChips(); render(); }\nfunction setBrand(m){ activeBrand=m; document.getElementById(\'q\').value=\'\'; buildChips(); render(); }\ndocument.getElementById(\'kpis\').innerHTML=\'<span><b>\'+brands.length+\'</b> marcas</span><span><b>\'+grupos.length+\'</b> clientes</span><span><b>\'+DATA.filter(r=>r.papel===\'EMBAIXADOR\').length+\'</b> embaixadores</span><span><b>\'+DATA.length+\'</b> vínculos</span>\';\ndocument.getElementById(\'q\').addEventListener(\'input\',()=>{ if(activeGrupo||activeBrand){activeGrupo=null;activeBrand=null;buildGrupos();buildChips();} render(); });\nbuildGrupos(); buildChips(); render();\n</script>\n</body>\n</html>\n'
open(OUT,"w",encoding="utf-8").write(TPL.replace("__DATA__", json.dumps(data,ensure_ascii=False)))
print("marcas.html gerado:",len(data),"->",OUT)
